//! Per-codec tile decoding benchmarks.
//!
//! Each benchmark decodes a fixed set of interior tiles from one fixture, so the measured path is
//! codec decompression + predictor reversal + typed array construction, with no I/O in the timed
//! region. Fixtures are generated by `benches/generate_fixtures.sh`; see `benches/README.md`.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use async_tiff::decoder::DecoderRegistry;
use async_tiff::metadata::cache::ReadaheadMetadataCache;
use async_tiff::metadata::TiffMetadataReader;
use async_tiff::reader::ObjectReader;
use async_tiff::Tile;
use criterion::{criterion_group, criterion_main, Criterion, Throughput};
use object_store::local::LocalFileSystem;
use tokio::runtime::Runtime;

/// Fixture file names, relative to `benches/data/`.
const FIXTURES: &[&str] = &[
    "deflate_u8_pred2.tif",
    "lzw_u8_pred2.tif",
    "zstd_u8_pred2.tif",
    "zstd_u8.tif",
    "jpeg_ycbcr.tif",
    "deflate_f32_pred3.tif",
];

/// Tile grid coordinates to decode: a 4x4 block of full 512px tiles that contain real imagery.
///
/// The source scene sits at the edge of the Sentinel-2 swath, so most of its 22x22 tile grid is
/// nodata. Columns 0..4 and rows 0..4 are fully covered by imagery (roughly 450-600 KB per tile
/// when deflate-compressed); nodata tiles compress to a few bytes and would make the benchmark
/// measure allocation rather than decoding.
fn tile_coords() -> Vec<(usize, usize)> {
    (0..4).flat_map(|y| (0..4).map(move |x| (x, y))).collect()
}

fn fixture_path(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("benches/data")
        .join(name)
}

/// Open a fixture and fetch the benchmark tiles (compressed bytes only).
async fn fetch_tiles(path: &Path) -> Vec<Tile> {
    let store = Arc::new(LocalFileSystem::new());
    let location = object_store::path::Path::from_filesystem_path(path).unwrap();
    let reader = ObjectReader::new(store, location);

    let cached = ReadaheadMetadataCache::new(reader.clone());
    let mut metadata_reader = TiffMetadataReader::try_open(&cached).await.unwrap();
    let ifds = metadata_reader.read_all_ifds(&cached).await.unwrap();
    let ifd = &ifds[0];

    ifd.fetch_tiles(&tile_coords(), &reader).await.unwrap()
}

fn decoded_byte_len(tiles: &[Tile], registry: &DecoderRegistry) -> usize {
    tiles
        .iter()
        .map(|tile| {
            let array = tile.clone().decode(registry).unwrap();
            let [h, w, c] = array.shape();
            h * w * c * array.data_type().unwrap().size()
        })
        .sum()
}

pub fn decode_benchmark(c: &mut Criterion) {
    let runtime = Runtime::new().unwrap();
    let registry = DecoderRegistry::default();

    let mut group = c.benchmark_group("decode");
    for name in FIXTURES {
        let path = fixture_path(name);
        assert!(
            path.exists(),
            "missing benchmark fixture {}; run benches/generate_fixtures.sh first",
            path.display()
        );

        let tiles = runtime.block_on(fetch_tiles(&path));
        let total_bytes = decoded_byte_len(&tiles, &registry);
        group.throughput(Throughput::Bytes(total_bytes as u64));

        let label = name.trim_end_matches(".tif");
        group.bench_function(label, |b| {
            b.iter(|| {
                for tile in &tiles {
                    let array = tile.clone().decode(&registry).unwrap();
                    std::hint::black_box(array);
                }
            })
        });
    }
    group.finish();
}

criterion_group!(benches, decode_benchmark);
criterion_main!(benches);
